create table if not exists public.redeem_codes (id uuid primary key default gen_random_uuid(),code text not null unique,discount_type text not null check(discount_type in('percent','fixed')),discount_value numeric(12,2) not null default 0,max_uses integer,used_count integer not null default 0,starts_at timestamptz,expires_at timestamptz,min_account_age_days integer not null default 0,user_id uuid references public.profiles(id) on delete cascade,active boolean not null default true,created_at timestamptz not null default now());
create or replace function public.validate_redeem_code(input_code text, order_amount numeric) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.redeem_codes; p public.profiles; discount numeric:=0; begin select * into r from public.redeem_codes where upper(code)=upper(trim(input_code)) and active=true for update; if r.id is null then raise exception 'Redeem code tidak ditemukan atau tidak aktif'; end if; if r.expires_at is not null and now()>r.expires_at then raise exception 'Redeem code sudah kedaluwarsa'; end if; select * into p from public.profiles where id=auth.uid(); if p.created_at > now()-make_interval(days=>r.min_account_age_days) then raise exception 'Umur akun belum memenuhi syarat'; end if; if r.discount_type='percent' then discount:=least(order_amount,order_amount*r.discount_value/100); else discount:=least(order_amount,r.discount_value); end if; return jsonb_build_object('id',r.id,'discount',discount,'final_amount',greatest(order_amount-discount,0)); end; $$;
grant execute on function public.validate_redeem_code(text,numeric) to authenticated;
